import path from 'node:path';
import { parseArgs } from 'node:util';
import { errorCode, errorMessage, InputError, UsageError, } from '@shahimat/ai-core';
import { OC3_TREE } from '#tree';
async function run(argv) {
    const { values, positionals } = parseArgs({
        args: argv,
        allowPositionals: true,
        options: {
            root: { type: 'string' },
            file: { type: 'string' },
            ticket: { type: 'string' },
            out: { type: 'string' },
            html: { type: 'string' },
            force: { type: 'boolean' },
            roles: { type: 'string' },
            help: { type: 'boolean', short: 'h' },
        },
    });
    if (values.help === true) {
        console.log(OC3_TREE.renderUsage(positionals));
        return 0;
    }
    const match = OC3_TREE.findCommand(positionals);
    if (match === undefined) {
        const last = positionals.at(-1);
        const prefix = positionals.slice(0, -1);
        if (last === 'help' && (prefix.length === 0 || OC3_TREE.isNamespace(prefix))) {
            console.log(OC3_TREE.renderUsage(prefix));
            return 0;
        }
        if (last === 'list' && (prefix.length === 0 || OC3_TREE.isNamespace(prefix))) {
            console.log(OC3_TREE.childrenOf(prefix).join('\n'));
            return 0;
        }
        if (positionals.length > 0 && OC3_TREE.isNamespace(positionals))
            throw new UsageError(`${positionals.join(' ')} — уровень, а не команда: ${OC3_TREE.childrenOf(positionals).join(' | ')}`);
        throw new UsageError(`неизвестная команда: ${positionals.join(' ') || '<пусто>'}`);
    }
    const args = {
        root: values.root !== undefined ? path.resolve(values.root) : path.resolve('.'),
        now: new Date(),
        params: match.params,
    };
    if (values.roles !== undefined)
        args.params = { ...args.params, roles: values.roles };
    if (values.file !== undefined)
        args.file = values.file;
    if (values.ticket !== undefined)
        args.ticket = values.ticket;
    if (values.out !== undefined)
        args.out = values.out;
    if (values.html !== undefined)
        args.html = values.html;
    if (values.force === true) {
        if (match.command.path.join(' ') !== 'expect report <file>')
            throw new UsageError('--force supported only for expect report');
        args.force = true;
    }
    return match.command.run(args);
}
export async function main(argv) {
    try {
        return await run(argv);
    }
    catch (error) {
        console.error(`ERROR: ${errorMessage(error)}`);
        if (error instanceof InputError)
            return 2;
        if (error instanceof UsageError) {
            console.error(OC3_TREE.renderUsage());
            return 2;
        }
        return (errorCode(error) ?? '').startsWith('ERR_PARSE_ARGS') ? 2 : 1;
    }
}

import { Plugin } from '@opencode/plugin';
import { registerBriefingGate } from '#briefing-gate';
import { isOperatorCentric, registerGuards } from '#guards';
import { registerOpsBrief } from '#ops-brief';
import { registerPlanBridge } from '#plan-bridge';
import { registerSessionBrief } from '#session-brief';
import { registerTools } from '#tools';
export default Plugin.define({
    id: 'oc3',
    async setup(ctx) {
        const root = ctx.location.directory;
        await registerPlanBridge(ctx);
        if (!(await isOperatorCentric(root)))
            return;
        await registerGuards(ctx);
        await registerBriefingGate(ctx);
        await registerTools(ctx);
        const cleanups = [await registerSessionBrief(ctx), await registerOpsBrief(ctx)];
        return async () => {
            for (const cleanup of cleanups)
                await cleanup();
        };
    },
});
export { appendBridgeEvent, plannerGuard, readBridge } from '#plan-bridge';
export { docsGuard } from '#guards';
